#!/bin/sh
# Generated by isoloom from isoloom.yml. Don't edit: change isoloom.yml and run
# `isoloom generate`. `isoloom check` fails when this file is out of date.
# The environment's checks, from the environment's networks. `isoloom test` runs it and reads the PASS/FAIL lines.
passed=0; failed=0
pass() { passed=$((passed+1)); echo "isoloom-check: PASS $1"; }
fail() { failed=$((failed+1)); echo "isoloom-check: FAIL $1: $2"; }
# _http URL -> the status code, 000 when nothing answers (curl, else wget, else bash).
_http() {
  if command -v curl >/dev/null 2>&1; then
    c=$(curl -sk -o /dev/null -m 5 -w '%{http_code}' "$1" 2>/dev/null)
  elif command -v wget >/dev/null 2>&1; then
    c=$(wget -q -S -O /dev/null -T 5 --no-check-certificate "$1" 2>&1 | sed -n 's/^ *HTTP\/[0-9.]* \([0-9][0-9][0-9]\).*/\1/p' | tail -n 1)
  else
    u=${1#*://}; hp=${u%%/*}; p=/${u#*/}; [ "$u" = "$hp" ] && p=/
    h=${hp%%:*}; port=${hp#*:}; [ "$hp" = "$h" ] && port=80
    c=$(H=$h P=$port U=$p timeout 5 bash -c 'exec 3<>/dev/tcp/$H/$P && printf "GET %s HTTP/1.0\r\nHost: %s\r\n\r\n" "$U" "$H" >&3 && read -r l <&3 && echo "$l"' 2>/dev/null | sed -n 's/^HTTP\/[0-9.]* \([0-9][0-9][0-9]\).*/\1/p')
  fi
  echo "${c:-000}"
}
_http_is() { [ "$(_http "$1")" = "$2" ]; }
_http_any() { [ "$(_http "$1")" != 000 ]; }
# _tcp HOST PORT -> 0 when it connects (nc, else bash).
_tcp() {
  if command -v nc >/dev/null 2>&1; then nc -z -w 5 "$1" "$2" >/dev/null 2>&1
  else H=$1 P=$2 timeout 5 bash -c 'exec 3<>/dev/tcp/$H/$P' >/dev/null 2>&1
  fi
}
# _exec COMMAND TEXT -> 0 when the command succeeds and its output contains TEXT (if any).
_exec() { out=$(sh -c "$1" 2>&1) && { [ -z "$2" ] || printf '%s\n' "$out" | grep -qF -- "$2"; }; }
# _retry SECONDS COMMAND... -> keeps trying every 2s until it passes or the time is up.
_retry() { _end=$(( $(date +%s) + $1 )); shift; while ! "$@"; do [ "$(date +%s)" -lt "$_end" ] || return 1; sleep 2; done; }

if _retry 300 _http_is 'http://crapi-web/' 200; then pass 'crAPI answers'; else fail 'crAPI answers' "expected HTTP 200 from http://crapi-web/, got $(_http 'http://crapi-web/')"; fi

if _retry 120 _http_is 'http://crapi-identity:8080/identity/health_check' 200; then pass 'the identity service is healthy'; else fail 'the identity service is healthy' "expected HTTP 200 from http://crapi-identity:8080/identity/health_check, got $(_http 'http://crapi-identity:8080/identity/health_check')"; fi

if _retry 120 _http_is 'http://crapi-community:8087/community/home' 200; then pass 'the community service answers'; else fail 'the community service answers' "expected HTTP 200 from http://crapi-community:8087/community/home, got $(_http 'http://crapi-community:8087/community/home')"; fi

if _retry 180 _http_is 'http://crapi-workshop:8000/workshop/health_check/' 200; then pass 'the workshop service is healthy'; else fail 'the workshop service is healthy' "expected HTTP 200 from http://crapi-workshop:8000/workshop/health_check/, got $(_http 'http://crapi-workshop:8000/workshop/health_check/')"; fi

echo '== checks/login.sh'
if _retry 120 sh -c 'cd /isoloom/project && sh checks/login.sh'; then pass 'a seeded user logs in and reads its dashboard'; else fail 'a seeded user logs in and reads its dashboard' "checks/login.sh exited non-zero"; fi

if _retry 30 _http_is 'http://mailhog:8025/' 200; then pass 'MailHog answers'; else fail 'MailHog answers' "expected HTTP 200 from http://mailhog:8025/, got $(_http 'http://mailhog:8025/')"; fi

if _retry 30 _tcp 'gateway-service' 443; then pass 'the payment gateway answers'; else fail 'the payment gateway answers' "nothing listens at gateway-service:443"; fi

echo "isoloom-check: END $passed passed, $failed failed"
[ "$failed" -eq 0 ]
